/**
 * @param {null|boolean|number|string|Array|Object} obj1
 * @param {null|boolean|number|string|Array|Object} obj2
 * @return {null|boolean|number|string|Array|Object}
 */
var deepMerge = function(obj1, obj2) {
    // typeof null === "object", so check null explicitly
    const isContainer = x => x !== null && typeof x === "object";

    // Primitives, null, or object-vs-array mismatch: obj2 wins
    if (!isContainer(obj1) || !isContainer(obj2) ||
        Array.isArray(obj1) !== Array.isArray(obj2)) {
        return obj2;
    }

    // Same kind of container: start from a shallow copy of obj1 (do not mutate inputs)
    const merged = Array.isArray(obj1) ? [...obj1] : { ...obj1 };

    // Arrays: keys are the indices "0", "1", ..., assigning past the end
    // extends the array, so the result has the longer length automatically
    for (const key of Object.keys(obj2)) {
        if (Object.prototype.hasOwnProperty.call(merged, key)) {
            merged[key] = deepMerge(merged[key], obj2[key]);
        } else {
            merged[key] = obj2[key];
        }
    }
    return merged;
};

/**
 * let obj1 = {"a": 1, "c": 3}, obj2 = {"a": 2, "b": 2};
 * deepMerge(obj1, obj2); // {"a": 2, "c": 3, "b": 2}
 */
